/// <summary>
/// This class is called when METPickDirectorDataEntitity has done the import.
/// </summary>
class METPickDirectorDataProcess
{
    SalesId salesId;
    guid processId;

}

Method.Source:
/// <summary>
/// Process the sales orders which are macthing with the METPickDirectorDataEntityStaging for the current execution.
/// </summary>
public void processSOForPickDirectorData()
{
    #OCCRetryCount
    System.Exception netExcepn;

    SalesLine salesLine;
    METPickDirectorData pickDirectorData;
    List qualifyingSalesLines = new List(Types::Int64);
    Map  qtyOverrideMap       = new Map(Types::Int64, Types::Real);
    boolean isDataExists;

    try
    {
        ttsbegin;
        this.updateReferenceIdforPickDirectorData();
        this.updateMetPickDirectorStatus(METPickDirectorStatuses::InProgress);

        SalesTable      salesTable = salesTable::find(salesId);
        METSalesLine    metSalesLine;
        InventQty       qtyPicked;

        while select pickDirectorData
            where pickDirectorData.SalesId == salesId
            join salesLine
                where salesLine.SalesId == pickDirectorData.SalesId
                && salesLine.LineNum == pickDirectorData.LineNum
                && salesLine.ItemId == pickDirectorData.ItemId
                && salesLine.SalesStatus == SalesStatus::Backorder
        {
            qtyPicked = pickDirectorData.QtyPicked;

            // Reservation
            if (qtyPicked > 0)
            {
                isDataExists = true;

                this.reserveSOLineQty(salesLine, qtyPicked);

                qualifyingSalesLines.addEnd(salesLine.RecId);
                // QtyPicked is already an inventory-unit quantity (same unit reserveSOLineQty
                // passes straight into InventUpd_Reservation::newMovement) - no sales-unit
                // conversion needed here.
                qtyOverrideMap.add(salesLine.RecId, qtyPicked);
            }
            else //Assumption is that no possibility to have negative qty.
            {
                if (salesTable.METAllowBackOrders)
                {
                    metSalesLine = salesLine.metSalesLine();

                    if(metSalesLine.RecId)
                    {
                        metSalesLine.selectForUpdate(true);
                        metSalesLine.OrderExtractStatus = METOrderExtractStatus::Open;
                        metSalesLine.update();
                    }
                }
                else
                {
                    salesLine.selectForUpdate(true);
                    SalesUpdateRemain::construct().updateDeliverRemainder(salesLine, 0, 0);
                }
            }
        }

        if (isDataExists)
        {
            // Generate and post picking list
            List pickingRouteIDList = this.createSalesPickingListSingleLine(qualifyingSalesLines, qtyOverrideMap);

            // Register picking list
            if (!pickingRouteIDList.empty())
            {
                this.registerPickingList(pickingRouteIDList);
            }
        }
        ttscommit;

        this.updateMetPickDirectorStatus(METPickDirectorStatuses::Processed);
    }
    catch (Exception::CLRError)
    {
        netExcepn = CLRInterop::getLastException();
        throw error(netExcepn.ToString());
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    catch
    {
        this.updateMetPickDirectorStatus(METPickDirectorStatuses::Error);
        exceptionTextFallThrough();
    }

}

/// <summary>
/// Reserves the sales order line with the quantity picked.
/// </summary>
/// <param name = "_salesLine">Sales line</param>
/// <param name = "_qtyPicked">Quantity to reserve</param>
public void reserveSOLineQty(SalesLine _salesLine, InventQty _qtyPicked)
{
    InventMovement movement = InventMovement::construct(_salesLine);
    InventUpd_Reservation reservation = InventUpd_Reservation::newMovement(movement, -_qtyPicked, true);
    reservation.updateNow();
}

/// <summary>
/// Generates and posts the picking list for the sales order lines with the quantity picked.
/// </summary>
/// <param name = "_qualifyingSalesLines">List of SalesLine RecIds to include on the picking list</param>
/// <param name = "_qtyOverrideMap">Map of SalesLine RecId to pick qty (inventory unit), from METPickDirectorData.QtyPicked</param>
/// <returns>List containing the created WMSPickingRouteID, if any</returns>
public List createSalesPickingListSingleLine(List _qualifyingSalesLines, Map _qtyOverrideMap)
{
    SalesTable salesTableLoc = SalesTable::find(salesId);
    WMSPickingRoute wmsPickingRoute = METSalesPickListGenerationService::construct()
        .generatePickList(salesTableLoc, _qualifyingSalesLines, false, _qtyOverrideMap);

    List list = new List(Types::String);

    if (wmsPickingRoute.RecId)
    {
        list.addEnd(wmsPickingRoute.PickingRouteID);
    }

    return list;
}

/// <summary>
/// Registers the picking list for the selected sales line.
/// </summary>
/// <param name = "_list">_list</param>
public void registerPickingList(List _list)
{
    WMSPickingRoute::finishMulti(_list.pack());
}

/// <summary>
/// Constructs the class instance.
/// </summary>
/// <param name = "_salesId">Sales order number</param>
/// <param name = "_processId">Process id</param>
/// <returns>METPickDirectorDataProcess</returns>
static METPickDirectorDataProcess construct(SalesId _salesId, guid _processId)
{
    if (!_salesId && !_processId)
    {
        throw error(strFmt("@SYS19306", funcName()));
    }

    return new METPickDirectorDataProcess(_salesId, _processId);
}

/// <summary>
/// Initializes the new memory for the class.
/// </summary>
/// <param name = "_salesId">Sales order number</param>
/// <param name = "_processId">Process id</param>
protected void new(SalesId _salesId, guid _processId)
{
    salesId = _salesId;
    processId = _processId;

}

/// <summary>
/// Updates the met pick director status.
/// </summary>
/// <param name = "_status">Status to update.</param>
private void updateMetPickDirectorStatus(METPickDirectorStatuses _status)
{
    METPickDirectorData pickDirectorData;
    SalesLine salesLine;

    update_recordset pickDirectorData
    setting PickDirectorStatus = _status
        join salesLine
        where salesLine.SalesId == pickDirectorData.SalesId
        && salesLine.LineNum == pickDirectorData.LineNum
        && pickDirectorData.SalesId == salesId;
}

/// <summary>
/// Updates the met pick director data referenceId's.
/// </summary>
private void updateReferenceIdforPickDirectorData()
{
     METPickDirectorData pickDirectorData;
    SalesLine salesLine;

    update_recordset pickDirectorData
        setting ReferenceId = processId
        join salesLine
            where salesLine.SalesId == pickDirectorData.SalesId
            && salesLine.LineNum == pickDirectorData.LineNum
            && pickDirectorData.SalesId == salesId;
}
